query AccountState($address: HexEncoded!) {
  contract(address: $address) { state }
  block { height }
}

query AccountHistory($address: HexEncoded!, $limit: Int) {
  contract(address: $address) {
    actions(limit: $limit) {
      __typename
      ... on ContractCall { entryPoint }
      transaction {
        hash id block { height }
        ... on RegularTransaction { zswapStartIndex zswapEndIndex transactionResult { status } }
        zswapLedgerEvents { id raw }
      }
    }
  }
}

